/** Offline integration gates; the JDBC target is restricted to an isolated loopback test port. */
public final class PlatformChecks {
  private static int assertions;
  private static JsonObject obj(String raw){return JsonParser.parseString(raw).getAsJsonObject();}
  private static void check(boolean ok,String message){assertions++;if(!ok)throw new AssertionError(message);}
  private interface Work{void run()throws Exception;}
  private static void denied(Work action,String message)throws Exception{try{action.run();throw new AssertionError(message);}catch(IllegalArgumentException|IllegalStateException|SecurityException expected){assertions++;}}
  private static void rosterPresenceChecks(ManagerStore store,Database.Config database,String archive,String run,UUID player)throws Exception{
    store.enableProfiles();
    JsonObject frame=obj("{runId:'"+run+"',archiveId:'"+archive+"',seq:4,at:"+System.currentTimeMillis()+",snapshot:{},players:[{id:'"+player+"',name:'LaterName',joinCount:4,totalOnlineMillis:5567,firstJoinEpochMillis:0,lastJoinEpochMillis:1234,ping:42,world:'minecraft:overworld',sessionMillis:15000}],stats:[],logins:[],acks:[],longTicks:[]}");
    store.ingest("test-platform",frame);
    var query=Map.of("q",player.toString());
    JsonObject projected=store.players(archive,query,true).getAsJsonArray("rows").get(0).getAsJsonObject();
    check(projected.get("isOnline").getAsBoolean(),"unified COALESCE numeric online flag remains true in roster JSON");
    check(projected.get("ping").getAsInt()==42&&projected.get("world").getAsString().equals("minecraft:overworld")&&projected.get("sessionMillis").getAsLong()==15000,"online roster retains live dimension latency and session");
    check(store.players(archive,Map.of("online","true"),true).get("total").getAsInt()==1,"online filter agrees with unified row presence");
    check(!store.players(archive,query,false).getAsJsonArray("rows").get(0).getAsJsonObject().get("isOnline").getAsBoolean(),"disconnected service never presents cached row as currently online");
    check(store.players(archive,Map.of("online","true"),false).get("total").getAsInt()==0,"disconnected online filter is empty");
    ManagerStore legacy=new ManagerStore(database);
    check(legacy.players(archive,query,true).getAsJsonArray("rows").get(0).getAsJsonObject().get("isOnline").getAsBoolean(),"direct JDBC boolean remains supported");
    try(Connection c=store.open()){ManagerStore.update(c,"UPDATE pm_players SET counter_warning=TRUE WHERE archive_id=? AND uuid=?",archive,player.toString());}
    check(store.players(archive,query,true).getAsJsonArray("rows").get(0).getAsJsonObject().get("counterWarning").getAsBoolean(),"unified numeric counter warning remains true");
    check(legacy.players(archive,query,true).getAsJsonArray("rows").get(0).getAsJsonObject().get("counterWarning").getAsBoolean(),"direct JDBC counter warning remains supported");
    frame.addProperty("seq",5);frame.add("players",new JsonArray());store.ingest("test-platform",frame);
    check(!store.players(archive,query,true).getAsJsonArray("rows").get(0).getAsJsonObject().get("isOnline").getAsBoolean(),"next empty snapshot marks the player offline");
    check(store.players(archive,Map.of("online","true"),true).get("total").getAsInt()==0,"online filter follows logout without losing the stored profile");
  }
  public static void main(String[] args)throws Exception{
    String base=System.getenv().getOrDefault("PM_TEST_JDBC_BASE","jdbc:mariadb://127.0.0.1:43317/");if(!base.matches("jdbc:mariadb://127\\.0\\.0\\.1:[0-9]+/"))throw new IllegalArgumentException("Only isolated loopback database allowed");String password=System.getenv().getOrDefault("PM_TEST_PASSWORD","");String db="pm_platform_"+UUID.randomUUID().toString().replace("-","");String restored=db+"_restored";Path folder=Files.createTempDirectory(Path.of("manager-service"),".platform-check-");
    try(Connection c=DriverManager.getConnection(base,"root",password)){c.createStatement().execute("CREATE DATABASE "+db+" CHARACTER SET utf8mb4");c.createStatement().execute("CREATE DATABASE "+restored+" CHARACTER SET utf8mb4");}
    Database.Config database=new Database.Config(base+db,"root",password);UUID owner=UUID.randomUUID(),player=UUID.randomUUID();ServiceConfig config=new ServiceConfig(database,null,true,"127.0.0.1",18805,"http://127.0.0.1:18805",List.of(owner),"data",null,true,"unified",12);
    try{
      // Losslessly imported core identity must project into modules without plugin participation.
      ManagerStore initial=new ManagerStore(database);initial.migrate();initial.register("test-platform",UUID.randomUUID()+":"+UUID.randomUUID());String run=UUID.randomUUID().toString(),world=UUID.randomUUID().toString();initial.hello("test-platform",obj("{runId:'"+run+"',worldId:'"+world+"',startedAt:"+(System.currentTimeMillis()-1000)+",info:{}}"));String archive=initial.createArchive(obj("{instanceId:'test-platform',worldId:'"+world+"',name:'Migration',version:'test',startedOn:'2026-10-27',active:true}"),"test").get("id").getAsString();
      try(Connection c=initial.open()){ManagerStore.update(c,"INSERT INTO pm_players(archive_id,uuid,name,name_sort,join_count,first_join,last_join,total_ms,payload) VALUES(?,?,?,?,?,?,?,?,?)",archive,player.toString(),"KnownBeforePlugins","a",3,0,1234,4567,"{}");}
      try(Connection c=initial.open()){for(String raw:List.of("{\"fake\":true}","{\"fake\":\"true\"}","{\"fake\":1}"))check(ManagerStore.rows(c,"SELECT COALESCE(JSON_UNQUOTE(JSON_EXTRACT(?,'$.fake')),'false') NOT IN ('true','1') allowed",raw).get(0).get("allowed").getAsInt()==0,"MariaDB fake true/string/number excluded");for(String raw:List.of("{\"fake\":false}","{}","{\"fake\":null}"))check(ManagerStore.rows(c,"SELECT COALESCE(JSON_UNQUOTE(JSON_EXTRACT(?,'$.fake')),'false') NOT IN ('true','1') allowed",raw).get(0).get("allowed").getAsInt()==1,"MariaDB real/missing/null retained");}
      try(ManagerController controller=new ManagerController(config,folder)){
        JsonObject profiles=controller.platform.profiles();check(profiles.getAsJsonArray("players").size()==1,"global roster imported once");check(profiles.getAsJsonArray("players").get(0).getAsJsonObject().get("firstJoinedAt").getAsLong()==0,"unknown historical first login remains zero");
        try(Connection c=controller.store.open()){check(ManagerStore.rows(c,"SELECT * FROM mt_players").isEmpty(),"migration does not manufacture Titles login");check(ManagerStore.rows(c,"SELECT * FROM df_players").isEmpty(),"migration does not manufacture fortune participation");check(ManagerStore.rows(c,"SELECT * FROM mt_notifications").isEmpty(),"migration creates no reward notification");}
        check(controller.titles.snapshot().players().containsKey(player),"Titles projects global directory");
        JsonObject roster=controller.fortunes.request("GET","/players",new JsonObject(),Map.of(),owner.toString(),Set.of());check(roster.get("total").getAsInt()==1,"fortunes projects global directory");
        JsonObject third=obj("{version:1,name:'Independent extension',label:'测试模块',scope:'global',fields:[{id:'enabled',type:'boolean',scope:'global',default:false,maxBytes:32},{id:'visits',type:'integer',scope:'archive',default:0,maxBytes:32}],tables:[]}");controller.platform.register("independent",third);controller.platform.register("independent",third);
        var hook=controller.platform.hook("independent",Set::of);JsonObject read=obj("{op:'storage.get',player:'"+player+"',field:'enabled'}");check(!hook.apply(read).get("value").getAsBoolean()&&hook.apply(read).get("revision").getAsLong()==0,"third module typed default without stored rows");
        JsonObject write=obj("{op:'storage.set',player:'"+player+"',field:'enabled',value:true,expectedRevision:0}");check(hook.apply(write).get("revision").getAsLong()==1,"third module optimistic write");denied(()->hook.apply(write),"stale revision refused");JsonObject foreign=read.deepCopy();foreign.addProperty("namespace","memorialtitles");denied(()->hook.apply(foreign),"namespace ownership enforced");
        JsonObject bad=write.deepCopy();bad.addProperty("expectedRevision",1);bad.addProperty("value","true");denied(()->hook.apply(bad),"boolean string rejected");bad.addProperty("field","unregistered");denied(()->hook.apply(bad),"unregistered field rejected");
        JsonObject scoped=obj("{op:'storage.set',player:'"+player+"',field:'visits',archiveId:'"+archive+"',value:4,expectedRevision:0}");check(hook.apply(scoped).get("value").getAsInt()==4,"archive scoped field supported");
        try(Connection c=controller.store.open()){ManagerStore.update(c,"UPDATE pm_archives SET status='archived' WHERE id=?",archive);}scoped.addProperty("expectedRevision",1);denied(()->hook.apply(scoped),"historical mutations refused");
        check(!controller.platform.loginContext(player.toString(),Set.of(player)).get("firstGlobalLogin").getAsBoolean(),"migration not a login context");
        controller.web=new PlatformWebServer(controller,new cn.pixelmc.memorialtitles.web.WebConfig(true,"127.0.0.1",18805,config.publicUrl(),480,List.of()),folder.resolve("platform"));controller.web.accounts.create("testowner",owner,"Test-Only-Pass-123!");
        HttpClient client=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();HttpRequest login=HttpRequest.newBuilder(URI.create(config.publicUrl()+"/api/login")).header("Content-Type","application/json").header("Origin",config.publicUrl()).POST(HttpRequest.BodyPublishers.ofString("{\"username\":\"testowner\",\"password\":\"Test-Only-Pass-123!\"}")).build();var loginResponse=client.send(login,HttpResponse.BodyHandlers.ofString());check(loginResponse.statusCode()==200,"platform owns account authentication");String csrf=obj(loginResponse.body()).get("csrf").getAsString();var generic=IntegrationChecks.send(client,config.publicUrl(),"/api/extensions/independent/storage/get",obj("{player:'"+player+"',field:'enabled'}"),csrf,config.publicUrl());check(generic.statusCode()==200&&obj(generic.body()).get("value").getAsBoolean(),"third module uses generic authenticated HTTP route");
        var title=new cn.pixelmc.memorialtitles.domain.Model.Title("platform-test",cn.pixelmc.memorialtitles.domain.Model.RichText.plain("纪念"),"","","","",0,0,true,true,1);
        controller.titles.saveTitle(cn.pixelmc.memorialtitles.service.TitleService.Actor.consoleActor(),title,0).get();controller.titles.grant(cn.pixelmc.memorialtitles.service.TitleService.Actor.consoleActor(),List.of(player),title.id(),"test").get();controller.titles.equip(player,title.id()).get();
        Path backup=controller.backupAll();try(var zip=new java.util.zip.ZipFile(backup.toFile())){check(zip.getEntry("database/df_records.json")!=null&&zip.getEntry("database/mt_owned.json")!=null&&zip.getEntry("database/pm_values.json")!=null,"one backup includes both modules and third namespace fields");check(zip.getEntry("database/pm_metrics.json")==null,"ephemeral telemetry excluded");check(zip.getEntry("files/platform/web-accounts.json")!=null,"platform accounts backed up");}
        ServiceConfig destination=new ServiceConfig(new Database.Config(base+restored,"root",password),null,true,"127.0.0.1",18806,"http://127.0.0.1:18806",List.of(),"data",null,true,"unified",12);Path restoreFolder=folder.resolve("restore");ServiceConfig recovered=ManagerRestore.restore(destination,restoreFolder,backup);ManagerRestore.complete(restoreFolder);check(recovered.owners().contains(owner),"owner restored without replacing target connection");
        ManagerStore restoredStore=new ManagerStore(destination.database());PlatformStore restoredPlatform=new PlatformStore(restoredStore);check(restoredPlatform.request("independent",read,Set.of()).get("value").getAsBoolean(),"generic storage survives full backup restore");check(new PlatformAccounts(restoreFolder.resolve("platform")).verify("testowner","Test-Only-Pass-123!")!=null,"password hash preserved");denied(()->ManagerRestore.restore(destination,restoreFolder,backup),"populated target cannot be overwritten");
        PlatformDeletion cleanup=new PlatformDeletion(controller.store,controller.platform,controller.web.avatars);JsonObject preview=cleanup.preview(player,Set.of());String firstStamp=preview.get("stamp").getAsString();denied(()->cleanup.delete(owner,player,firstStamp,"KnownBeforePlugins",Set.of(player)),"online global deletion refused");String recovery=cleanup.delete(owner,player,preview.get("stamp").getAsString(),"KnownBeforePlugins",Set.of());check(controller.platform.profile(player.toString()).get("profile").isJsonNull(),"global deletion removes identity");try(Connection c=controller.store.open()){ManagerStore.update(c,"UPDATE pm_archives SET status='active' WHERE id=?",archive);}JsonObject replay=obj("{runId:'"+run+"',archiveId:'"+archive+"',seq:1,at:"+System.currentTimeMillis()+",snapshot:{},players:[],stats:[{id:'"+player+"',name:'KnownBeforePlugins',joinCount:3,totalOnlineMillis:4567,firstJoinEpochMillis:0,lastJoinEpochMillis:1234}],logins:[{id:'old-login',sessionId:'old',uuid:'"+player+"',name:'KnownBeforePlugins',at:1234}],acks:[],longTicks:[]}");controller.store.ingest("test-platform",replay);controller.platform.backfill();check(controller.platform.profile(player.toString()).get("profile").isJsonNull(),"replayed stats and old login journal cannot resurrect deleted directory");try(Connection c=controller.store.open()){check(ManagerStore.rows(c,"SELECT * FROM mt_owned WHERE player=?",player.toString()).isEmpty(),"global cleanup includes title ownership");check(ManagerStore.rows(c,"SELECT * FROM pm_values WHERE uuid=?",player.toString()).isEmpty(),"global cleanup includes third module fields");}
        cleanup.restore(owner,recovery,Set.of());check(!controller.platform.profile(player.toString()).get("profile").isJsonNull()&&controller.platform.request("independent",read,Set.of()).get("value").getAsBoolean(),"one recovery restores identity and registered module fields");try(Connection c=controller.store.open()){check(ManagerStore.rows(c,"SELECT * FROM mt_owned WHERE player=?",player.toString()).size()==1,"global recovery preserves title ownership");}denied(()->cleanup.restore(owner,recovery,Set.of()),"recovery cannot be replayed");
        preview=cleanup.preview(player,Set.of());String conflict=cleanup.delete(owner,player,preview.get("stamp").getAsString(),"KnownBeforePlugins",Set.of());try(Connection c=controller.store.open()){PlatformStore.identity(c,player.toString(),"OldCheckpoint",1,2);}check(controller.platform.profile(player.toString()).get("profile").isJsonNull(),"tombstone blocks old statistics from resurrecting profile");try(Connection c=controller.store.open()){PlatformStore.admission(c,"test-platform",archive,obj("{id:'new-login-event',uuid:'"+player+"',name:'LaterName',at:"+(System.currentTimeMillis()+1)+"}"));}JsonObject next=obj("{runId:'"+run+"',archiveId:'"+archive+"',seq:2,at:"+System.currentTimeMillis()+",snapshot:{},players:[],stats:[{id:'"+player+"',name:'LaterName',joinCount:4,totalOnlineMillis:5567,firstJoinEpochMillis:0,lastJoinEpochMillis:"+System.currentTimeMillis()+"}],logins:[],acks:[],longTicks:[]}");controller.store.ingest("test-platform",next);JsonObject fresh=controller.store.players(archive,Map.of(),false).getAsJsonArray("rows").get(0).getAsJsonObject();check(fresh.get("joinCount").getAsLong()==1&&fresh.get("totalOnlineMillis").getAsLong()==1000,"new real session applies counter baselines without restoring cleared totals");check(!controller.platform.loginContext(player.toString(),Set.of(player)).get("firstGlobalLogin").getAsBoolean(),"return after deletion never becomes first-global reward");denied(()->cleanup.restore(owner,conflict,Set.of()),"later player data blocks forced recovery");
        String fake=UUID.randomUUID().toString();try(Connection c=controller.store.open()){ManagerStore.update(c,"INSERT INTO pm_players(archive_id,uuid,name,name_sort,join_count,first_join,last_join,total_ms,payload) VALUES(?,?,?,?,?,?,?,?,?)",archive,fake,"alex","a",2,1,2,1000,"{}");PlatformStore.identity(c,fake,"alex",1,2);}check(!controller.platform.profile(fake).get("profile").isJsonNull(),"old unmarked profile exists before fresh fake evidence");JsonObject fakeFrame=obj("{runId:'"+run+"',archiveId:'"+archive+"',seq:3,at:"+System.currentTimeMillis()+",snapshot:{},players:[{id:'"+fake+"',name:'alex',fake:true}],stats:[{id:'"+fake+"',name:'alex',joinCount:2,totalOnlineMillis:1000,firstJoinEpochMillis:1,lastJoinEpochMillis:2}],logins:[],acks:[],longTicks:[]}");controller.store.ingest("test-platform",fakeFrame);controller.platform.backfill();check(controller.platform.profile(fake).get("profile").isJsonNull()&&controller.platform.profiles().getAsJsonArray("players").size()==1,"fresh fake classification overrides stale unmarked stats without directory resurrection");check(controller.store.state("test-platform","").getAsJsonObject("totals").get("players").getAsInt()==1,"core archive counts share the real global roster");try(Connection c=controller.store.open()){check(ManagerStore.rows(c,"SELECT uuid FROM pm_players WHERE uuid=?",fake).size()==1,"fake historical business rows preserved for audit/rollback");}
      }
      // Exercise the numeric flags produced by the unified directory's LEFT JOIN/COALESCE.
      rosterPresenceChecks(initial,database,archive,run,player);
      // Disabling Titles removes its database dependency but not accounts, profiles or avatars.
      ServiceConfig noTitles=new ServiceConfig(database,null,false,"127.0.0.1",18807,"http://127.0.0.1:18807",List.of(owner),"data",null,false,"unified",12);try(ManagerController controller=new ManagerController(noTitles,folder.resolve("no-titles"))){check(controller.titles==null&&controller.platform.profiles().getAsJsonArray("players").size()==1,"platform runs with Titles disabled");controller.web=new PlatformWebServer(controller,new cn.pixelmc.memorialtitles.web.WebConfig(true,"127.0.0.1",18807,noTitles.publicUrl(),480,List.of()),folder.resolve("no-titles/platform"));controller.web.accounts.create("notitles",owner,"Test-Only-Pass-123!");check(controller.web.accounts.verify("notitles","Test-Only-Pass-123!")!=null,"no Titles account dependency");}
      System.out.println("Unified platform integration checks passed: "+assertions);
    }finally{try(Connection c=DriverManager.getConnection(base,"root",password)){c.createStatement().execute("DROP DATABASE "+db);c.createStatement().execute("DROP DATABASE "+restored);}try(var paths=Files.walk(folder)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
  }
}
